\";s:15:\"Emily Rodriguez\";s:13:\"customer_role\";s:14:\"Happy Customer\";s:7:\"content\";s:121:\"The pasta carbonara is authentic and delicious! Love the easy ordering process and the food always arrives hot and fresh.\";s:6:\"rating\";i:5;s:6:\"avatar\";s:11:\"👩‍🦱\";}}s:5:\"stats\";a:4:{s:10:\"totalItems\";i:32;s:13:\"averageRating\";d:4.9;s:14:\"totalCustomers\";i:11;s:19:\"averageDeliveryTime\";i:30;}}', 1765363360);


